#[test]
fn guest_blocks_anonymous() {
    property(114, N, |c| {
        let out = k::middleware::guest_access_guard(false, &c.o, &c.req);
        if !matches!(out, Outcome::Next { .. }) || !no_credential(&c.req) {
            return false;
        }
        assert!(allowlisted(&c.req.path), "{:?}", c.req);
        true
    });
}

/// Run one upstream middleware on `req` in front of the capturing handler,
/// inside `client_ip`'s request scope. Fresh service state (and so empty
/// caches) per call.
pub fn run(rt: &tokio::runtime::Runtime, layer: Layer, db: &Db, oracle: &k::trusted::Oracle,
           client_ip: Option<k::net::IpAddr>, req: Request) -> (Vec<k::resolve::Write>, k::middleware::Outcome) {
    let (pool, backend) = pool(db);
    let auth_service = Arc::new(AuthService::with_oracle(pool.clone(), Arc::new(oracle.clone())));
    let router = Router::new().fallback(capture);
    let router = match layer {
        Layer::RepoVisibility => {
            let state = RepoVisibilityState {
                auth_service,
                db: pool.clone(),
                repo_cache: Default::default(),
                repo_miss_cache: Default::default(),
                permission_service: Arc::new(PermissionService::new(pool.clone())),
            };
            router.layer(axum::middleware::from_fn_with_state(state, up_auth::repo_visibility_middleware))
        }
        Layer::Auth => router.layer(axum::middleware::from_fn_with_state(auth_service, up_auth::auth_middleware)),
        Layer::OptionalAuth => {
            router.layer(axum::middleware::from_fn_with_state(auth_service, up_auth::optional_auth_middleware))
        }
        Layer::Admin => router.layer(axum::middleware::from_fn_with_state(auth_service, up_auth::admin_middleware)),
        Layer::Guest(enabled) => router.layer(axum::middleware::from_fn_with_state(
            GuestAccessState { guest_access_enabled: enabled, auth_service }, guest_access_guard)),
    };
    let fut = async move {
        let resp = router.oneshot(req).await.unwrap();
        outcome(resp).await
    };
    let out = rt.block_on(crate::api::middleware::client_ip::with_client_ip_scope(client_ip.map(stdip), fut));
    let writes = backend.writes.lock().unwrap().clone();
    (writes, out)
}

#[test]
fn guest_access_guard_agrees() {
    for (enabled, seed) in [(false, 5), (true, 6)] {
        middleware_agrees(Layer::Guest(enabled), seed, 60_000,
            if enabled {
                |_: &k::tables::Db, o: &k::trusted::Oracle, _: Option<k::net::IpAddr>, req: &k::http::Request| {
                    (vec![], k::middleware::guest_access_guard(true, o, req))
                }
            } else {
                |_: &k::tables::Db, o: &k::trusted::Oracle, _: Option<k::net::IpAddr>, req: &k::http::Request| {
                    (vec![], k::middleware::guest_access_guard(false, o, req))
                }
            },
            if enabled { &["Next(auth=false, ticket=false)"] } else { &[
                "Next(auth=false, ticket=false)", "ServiceUnavailable", "OciUnauthorized",
                "GuestUnauthorized { for_browser: true }", "GuestUnauthorized { for_browser: false }",
            ] });
    }
}

#[test]
fn header_predicates_agree() {
    let mut r = Rng(14);
    let mut csrf = 0;
    for _ in 0..300_000 {
        let m = rand_method(&mut r);
        let hs = headers(&mut r);
        let Some((req, kreq)) = request(m, "/x", None, &hs) else { continue };
        let h: &HeaderMap = req.headers();
        let v = k::http::violates_csrf_contract(m, &kreq.headers);
        assert_eq!(v, up::probe::violates_csrf_contract(&http_method(m), h), "{kreq:?}");
        csrf += v as usize;
        assert_eq!(k::http::is_browser_request(&kreq.headers), up::is_browser_request(h));
        assert_eq!(k::http::has_header_credential(&kreq.headers), up::probe::has_header_credential(h));
        assert_eq!(k::http::request_carries_credentials(&kreq.headers), up::request_carries_credentials(h));
        assert_eq!(k::http::declares_same_origin(&kreq.headers), up::probe::declares_same_origin(h));
        let mut o = k::trusted::Oracle { jwt: vec![], api_tokens: vec![], passwords: vec![], base64: vec![], ip: vec![] };
        fill_base64(&mut o, &kreq.headers);
        assert_eq!(k::resolve::extract_bearer_credentials(&o, &kreq.headers),
                   up::extract_bearer_credentials(h).map(|(a, c)| (b(&a), b(&c))));
        if let Some(v) = kreq.headers.iter().find(|x| x.0 == b"authorization").map(|x| x.1.clone()) {
            if let Ok(s) = std::str::from_utf8(&v) {
                for i in 0..=s.len() {
                    if s.is_char_boundary(i) {
                        assert_eq!(k::resolve::decode_basic_credentials(&o, &v[i..]),
                                   up::probe::decode_basic_credentials(&s[i..]).map(|(a, c)| (b(&a), b(&c))));
                    }
                }
            }
        }
    }
    assert!(csrf > 100, "{csrf}");
}
